import{z as i,x as B,o as t,c as p,q as A,j as o,D as e,d as l,s as r,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"损失曲线的阶段","description":"","frontmatter":{"title":"损失曲线的阶段","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/loss-curve-phases.md","filePath":"llm/loss-curve-phases.md","lastUpdated":1791063341000}'),d={name:"llm/loss-curve-phases.md"};function C(m,a,u,D,g,k){const n=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="损失曲线的阶段" tabindex="-1">损失曲线的阶段 <a class="header-anchor" href="#损失曲线的阶段" aria-label="Permalink to &quot;损失曲线的阶段&quot;">​</a></h1><div class="epigraph"><p>学习曲线很少是一条光滑幂律；同一张图上叠着快速压熵、记局部模式、以及偶发的尖峰，必须按阶段读，不能只读终点。</p><footer>—— 幂律背景见 Kaplan et al., 2020；双下降见 Nakkiran et al., ICLR 2020；训练动态里的回路形成见 Olsson et al., Induction Heads, 2022</footer></div><p><a href="/llm/perplexity-bpb">上一课</a>把纵轴单位钉成 token CE / PPL。缺口是横轴上的<strong>形状</strong>。主干的 <a href="/llm/kaplan-scaling">Kaplan</a> 与 <a href="/llm/chinchilla">Chinchilla</a> 描述的是终点损失对 \\(N,D,C\\) 的幂律，不描述训练过程内部何时在压 unigram、何时出现 induction、何时尖峰。本课把一条预训练曲线分成可操作的阶段，作为「反传与初始化」单元的收束：后面「训练为什么会炸」默认你会区分「还在正常降」和「已经离开可工作盆地」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机初始化的 CE 靠近 \\(\\log|V|\\)。前几千 step（含 warmup）通常陡降：模型先学空格、标点、高频 token 的边际分布，PPL 从词表大小掉到三位数。这段斜率对架构不敏感，对学习率是否炸却敏感——若这里就不降，是初始化或 \\(\\eta\\) 错了，不是数据不够。</p><p><span class="marginnote">代入数字：词表 5 万时，随机初始化的 CE 约为 \\(\\ln(50000) \\approx 10.8\\)，对应 PPL 约 5 万——等于闭着眼睛按词频瞎猜。压熵段要做的就是把这一项打到三位数（PPL 几百），只靠学会「哪些 token 常出现」这一件事。</span></p><p>随后进入长时间的缓降，近似 Kaplan 说的幂律段：对数损失对对数 token 近线性。中间会插入若干突变：Olsson 等人在小模型上看到 induction head 形成时损失阶跃下降；大模型上同一机制被摊在更多层里，曲线更平滑，但不表示没有回路在形成。Nakkiran 等人的双下降提醒：插值附近测试损失可能先升后降，不要把验证 CE 的一次回升自动判为过拟合终止。</p><p>尖峰是第三种形状：若干 step 内训练 CE 竖起，再掉回或掉不回。主干 <a href="/llm/grad-clip-loss-spike">梯度裁剪</a> 已经说裁剪挡住爆炸、不解释尖峰。本课只要你在日志里给尖峰打标，不要把它们平均进幂律拟合。</p><p><span class="marginnote">把整条曲线拟合一条 \\(L=aC^{-b}\\) 时，若把 warmup 段和尖峰段算进去，\\(b\\) 会被污染。拟合课会展开；这里先规定：阶段边界是拟合之前的标注工作。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读曲线时至少切四段（边界用 token 数而不是 wall-clock）：</p><ol><li><strong>Warmup / 压熵。</strong> \\(\\eta\\) 从近 0 升到峰值。验收：CE 单调降、grad norm 不长期贴 clip、max logit 仍 \\(O(10)\\) 量级。</li></ol><p><span class="marginnote">warmup 可以想象成先热车再上路：参数还是随机数时，一上来就用大学习率猛更新，容易把模型一脚踢出「可工作盆地」。所以学习率从近 0 缓缓升到峰值，等梯度统计稳定了再放开跑——这是把「起步阶段」和「巡航阶段」分开对待。</span></p><ol start="2"><li><strong>幂律降。</strong> 峰值 \\(\\eta\\) 或 WSD 稳定段。验收：对数-对数斜率稳定；数据配比若切换，允许斜率改变，应在日志打事件。</li><li><strong>突变 / 回路。</strong> 局部陡降或平台后的再降。应对照下游探针（induction、复制、简单算术），不要只看 CE。</li><li><strong>衰减段。</strong> 余弦尾或 cooldown。CE 再降一截是日程效果；若反升，检查权重衰减与 \\(\\eta\\) 是否把参数拉离盆地。</li></ol><p>每段记录：token CE、grad norm 分位数、注意力 logit 分位数、输出 LSE。后四项是下一单元的传感器，本课只要求开始记，不解释阈值。</p>',15)),(t(),o(s,null,{default:e(()=>[r(n,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%9B%B2%E7%BA%BF%E5%BD%A2%E7%8A%B6%E5%BC%82%E5%B8%B8%22%5D%20--%3E%20Q1%7B%22%E5%8F%91%E7%94%9F%E5%9C%A8%E5%89%8D%E5%87%A0%E5%8D%83%20step%3F%22%7D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20C1%5B%22%E6%9F%A5%E5%88%9D%E5%A7%8B%E5%8C%96%E4%B8%8E%20eta%EF%BC%9A%E5%8E%8B%E7%86%B5%E6%AE%B5%E4%B8%8D%E9%99%8D%E4%B8%8D%E6%98%AF%E6%95%B0%E6%8D%AE%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20Q1%20--%3E%7C%E5%90%A6%7C%20Q2%7B%22%E5%AF%B9%E6%95%B0-%E5%AF%B9%E6%95%B0%E6%96%9C%E7%8E%87%E5%8F%98%E4%BA%86%3F%22%7D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20C2%5B%22%E8%AE%B0%E6%95%B0%E6%8D%AE%E9%85%8D%E6%AF%94%E5%88%87%E6%8D%A2%E4%BA%8B%E4%BB%B6%EF%BC%8C%E5%86%8D%E8%B0%88%E6%8B%9F%E5%90%88%22%5D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20Q3%7B%22%E9%AA%8C%E8%AF%81%20CE%20%E5%9B%9E%E5%8D%87%3F%22%7D%0A%20%20Q3%20--%3E%7C%E6%98%AF%7C%20C3%5B%22%E5%85%88%E6%83%B3%E5%8F%8C%E4%B8%8B%E9%99%8D%EF%BC%8C%E4%B8%8D%E8%A6%81%E8%87%AA%E5%8A%A8%E5%88%A4%E8%BF%87%E6%8B%9F%E5%90%88%E7%BB%88%E6%AD%A2%22%5D%0A%20%20Q3%20--%3E%7C%E5%90%A6%7C%20C4%5B%22%E8%AE%AD%E7%BB%83%20CE%20%E7%AB%96%E8%B5%B7%EF%BC%9A%E6%89%93%E5%B0%96%E5%B3%B0%E6%A0%87%EF%BC%8C%E5%89%94%E5%87%BA%E5%B9%82%E5%BE%8B%E6%8B%9F%E5%90%88%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"压熵段主要改输出头与嵌入：unigram 统计进 \\(W_{\\mathrm{out}}\\) 与 \\(E\\)。幂律段才是残差流上的特征学习。因此在压熵段做架构消融（改深度、改头数）往往看不出差别——差别被输出层的快速拟合盖住。小模型代理实验应把评测放在幂律段之后，或报告「同等 token 下的斜率」，而不是只比 1B token 的终点。",-1)),a[5]||(a[5]=E("p",null,"Grokking（Power 等）在小算法任务上显示：训练 CE 已近 0 之后，验证准确率才突然升。预训练几乎看不到干净的 grokking，但同一教训适用：终点训练 CE 不能单独当「已经学会」。阶段 3 的下游探针是为这个服务的。",-1)),a[6]||(a[6]=E("h2",{id:"边界",tabindex:"-1"},[l("边界 "),E("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[7]||(a[7]=E("p",null,"本课不诊断尖峰原因（坏 batch、\\(\\beta_2\\)、logit 增长），那是下一单元。也不把双下降、grokking、induction 合成一条普遍时间表：它们出现的 token 数随宽度与数据变。Chinchilla 的计算最优点是终点预算，不是「必须在阶段 2 结束时停」——过度训练进阶段 4 对推理部署常常更优，缩放单元会写。",-1)),(t(),o(s,null,{default:e(()=>[r(n,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E9%9A%8F%E6%9C%BA%20CE%20%E8%BF%91%20log%7CV%7C%22%5D%20--%3E%20W%5B%22%E5%8E%8B%E7%86%B5%20%2F%20warmup%22%5D%0A%20%20W%20--%3E%20P%5B%22%E5%B9%82%E5%BE%8B%E7%BC%93%E9%99%8D%22%5D%0A%20%20P%20--%3E%20J%5B%22%E5%8F%AF%E9%80%89%E7%AA%81%E5%8F%98%E4%B8%8E%E5%B0%96%E5%B3%B0%22%5D%0A%20%20J%20--%3E%20D%5B%22%E6%97%A5%E7%A8%8B%E8%A1%B0%E5%87%8F%20%2F%20cooldown%22%5D%0A%20%20D%20--%3E%20E%5B%22%E7%BB%88%E7%82%B9%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=E("h2",{id:"小结",tabindex:"-1"},[l("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[9]||(a[9]=E("ul",null,[E("li",null,"预训练曲线至少分压熵、幂律、突变/尖峰、衰减四段，用 token 对齐。"),E("li",null,"压熵段验初始化与 \\(\\eta\\)；幂律段才适合架构消融；尖峰不要拟合进幂律。"),E("li",null,"终点训练 CE 不等于已学会；下游探针补在突变段。"),E("li",null,"传感器（grad、注意力 logit、LSE）从此课开始记，解释留给稳定性单元。"),E("li",null,"出处：Kaplan et al., 2020；Nakkiran et al., ICLR 2020；Olsson et al., 2022。")],-1))])}const c=i(d,[["render",C]]);export{h as __pageData,c as default};
